macro_rules! item_table {
    (@get_item_id $py:expr, None) => {
        None
    };
    (@get_item_id $py:expr, $get_item_id:ident) => {
        Some(get_item_id()[stringify!($get_item_id)].into_py_any($py)?)
    };
    (@get_item_id $py:expr, $get_item_id:expr) => {
        Some($get_item_id.into_py_any($py)?)
    };
    ($($name:expr => ($kind:expr, $progressive:expr, $get_item_id:tt, [$($special_key:expr => $special_value:expr),*]),)*) => {
        fn item_table(py: Python<'_>) -> PyResult<IndexMap<&'static str, (&'static str, Option<bool>, Option<Py<PyAny>>, IndexMap<&'static str, Py<PyAny>>)>> {
            Ok(collect![
                $(
                    $name => ($kind, $progressive, item_table!(@get_item_id py, $get_item_id), {
                        #[allow(unused_mut)] let mut special = IndexMap::default();
                        $(
                            special.insert($special_key, $special_value.into_py_any(py)?);
                        )*
                        special
                    }),
                )*
            ])
        }
    };
}

