pub(crate) fn module(py: Python<'_>) -> PyResult<Bound<'_, PyModule>> {
    let m = PyModule::new(py, "item_list")?;
    let mod_get_item_id = PyModule::new(py, "GetItemId")?;
    for (name, value) in get_item_id() {
        mod_get_item_id.add(name, value)?;
    }
    m.add_submodule(&mod_get_item_id)?;
    m.add("item_table", item_table(py)?)?;
    Ok(m)
}
